// This is the PAID half of the ZoomInfo pipeline, deliberately separate
// from workflow 30's free Discover -- per testing_plan.md Phase 4's
// architecture decision, one deliberate click/call per selected row (or a
// small batch), never an automatic always-enrich-everything sweep like
// CoreClaw's. Accepts either {place_cid} (single) or {place_cids:[...]}
// (batch), hard-capped at MAX_BATCH so a typo or accidental request can't
// blow through a big chunk of the credit budget in one call.
const MAX_BATCH = 10;
const b = $json.body || {};
let ids = [];
if (Array.isArray(b.place_cids)) ids = b.place_cids.map(String);
else if (b.place_cid) ids = [String(b.place_cid)];
if (!ids.length) throw new Error('Need place_cid or place_cids (array) -- these are ZoomInfo companyIds from a prior Discover run.');
if (ids.length > MAX_BATCH) throw new Error(`Requested ${ids.length} companies in one call -- capped at ${MAX_BATCH} to keep credit spend deliberate and predictable. Split into smaller batches.`);
const department = (b.department || 'C-Suite,Operations').trim();
return [{ json: { place_cids: ids, department } }];

// Static-data accumulator, same convention as wf25/wf30 -- one item per
// place_cid, reset on every fresh call.
const ws = $getWorkflowStaticData('global');
ws.rows = [];
const ctx = $json;
return (ctx.place_cids || []).map(id => ({ json: { place_cid: id, department: ctx.department } }));

// Real request shape confirmed live 2026-08-03: {data:{type:"CompanyEnrich",
// attributes:{matchCompanyInput:[{companyId}], outputFields:[...]}}}.
// companyId is an INTEGER here.
const ctx = $json;
const outputFields = [
  'id', 'name', 'website', 'phone', 'street', 'city', 'state', 'zipCode', 'country',
  'employeeCount', 'revenue', 'primaryIndustry', 'subUnitType',
  'parentId', 'parentName', 'ultimateParentId', 'ultimateParentName',
  'numberOfContactsInZoomInfo'
];
return [{ json: {
  ...ctx,
  requestBody: { data: { type: 'CompanyEnrich', attributes: { matchCompanyInput: [{ companyId: parseInt(ctx.place_cid, 10) }], outputFields } } }
} }];

// PARSING QUIRK (found 2026-08-03 live in n8n): ZoomInfo's
// application/vnd.api+json Content-Type isn't autodetected as JSON, so
// the real response can arrive as {data: "<json string>"} instead of a
// parsed object.
function parseResp(raw) {
  if (raw && typeof raw.data === 'string') {
    try { return JSON.parse(raw.data); } catch (e) { return raw; }
  }
  return raw;
}
const prev = $('Reset accumulator + fan out place_cids').first().json;
const enrichResp = parseResp($json || {});
const row = Array.isArray(enrichResp.data) ? enrichResp.data[0] : null;
const matchStatus = row && row.meta ? row.meta.matchStatus : (enrichResp.errors ? 'ERROR' : 'NO_MATCH');
const a = row ? (row.attributes || {}) : {};
// BUG FIX 2026-08-03: ZoomInfo's JSON:API responses put `id` at the TOP
// LEVEL of the resource object (row.id), never inside row.attributes.
// Reading row.attributes.id silently returned null even on a real
// FULL_MATCH, which incorrectly routed every enrich_company call into the
// "no match" branch below regardless of match_status.
const matchedCompanyId = row ? row.id : null;
return [{ json: {
  place_cid: prev.place_cid,
  department: prev.department,
  match_status: matchStatus,
  matched_company_id: matchedCompanyId,
  company: a
} }];

// No match (or error) on Enrich Company -- no credit was charged for this
// record, and there's nothing to write beyond a status note. Skip straight
// to the accumulator; don't chain hierarchy/org chart/contact calls
// against a company that doesn't exist.
const ctx = $json;
const ws = $getWorkflowStaticData('global');
ws.rows = ws.rows || [];
ws.rows.push({
  place_cid: ctx.place_cid,
  enrich_status: ctx.match_status,
  note: `Enrich Company match status was ${ctx.match_status} -- no data to write.`
});
return [{ json: ctx }];

const ctx = $json;
return [{ json: {
  ...ctx,
  requestBody: {
    data: {
      type: 'CorporateHierarchyEnrich',
      attributes: { matchCompanyInput: [{ companyId: parseInt(ctx.matched_company_id, 10) }], outputFields: ['companyId', 'familyTree', 'parentage'] }
    }
  }
} }];

// subUnitType "Unspecified" means "no hierarchy classification on file",
// not "flagged as a sub-unit" -- confirmed live 2026-08-03 (Coast
// Fulfillment came back Unspecified with both parent fields null, i.e.
// genuinely independent). Only treat it as a real flag when subUnitType
// is a meaningful non-Unspecified value OR a parent name is populated.
function parseResp(raw) {
  if (raw && typeof raw.data === 'string') {
    try { return JSON.parse(raw.data); } catch (e) { return raw; }
  }
  return raw;
}
const prev = $('Extract matched companyId').first().json;
const hierarchyResp = parseResp($json || {});
const hierarchyRow = Array.isArray(hierarchyResp.data) ? hierarchyResp.data[0] : null;
const hAttrs = hierarchyRow && hierarchyRow.type === 'CorporateHierarchy' ? (hierarchyRow.attributes || {}) : null;
const a = prev.company || {};
const hasParentSignal = !!(a.parentName || a.ultimateParentName);
const isFlaggedSubUnit = !!(a.subUnitType && a.subUnitType !== 'Unspecified');
return [{ json: {
  place_cid: prev.place_cid,
  department: prev.department,
  matched_company_id: prev.matched_company_id,
  match_status: prev.match_status,
  company: a,
  hierarchy_type: (isFlaggedSubUnit || hasParentSignal) ? (a.subUnitType || 'Flagged') : null,
  parent_company: hasParentSignal ? (a.ultimateParentName || a.parentName) : null,
  corporate_family_tree: hAttrs ? (hAttrs.familyTree || null) : null
} }];

// Real request shape confirmed live 2026-08-03: {data:{type:"OrgChartEnrich",
// attributes:{companyId:"<string>", department:"<comma-separated string>"}}}.
// companyId is a STRING here (unlike Enrich Company/Corporate Hierarchy).
const ctx = $json;
return [{ json: {
  ...ctx,
  requestBody: { data: { type: 'OrgChartEnrich', attributes: { companyId: String(ctx.matched_company_id), department: ctx.department } } }
} }];

// Picks the single most senior org chart candidate (lowest orgChartTier =
// most senior, confirmed live 2026-08-03) -- this is the ONE person worth
// spending an Enrich Contact credit on, per the search-then-reveal
// discipline established in wf27/wf28/wf29. Coverage on very small
// companies can be thin (a real live test returned exactly ONE contact,
// no C-Suite match at all) -- that's a real data limit, not a bug.
function parseResp(raw) {
  if (raw && typeof raw.data === 'string') {
    try { return JSON.parse(raw.data); } catch (e) { return raw; }
  }
  return raw;
}
const prev = $('Merge company + hierarchy').first().json;
const resp = parseResp($json || {});
const rows = Array.isArray(resp.data) ? resp.data : [];
const candidates = rows.map(r => {
  const a = r.attributes || {};
  return {
    person_id: r.id || null,
    full_name: [a.firstName, a.middleName, a.lastName].filter(Boolean).join(' ') || null,
    title: a.title || null,
    org_chart_tier: (typeof a.orgChartTier === 'number') ? a.orgChartTier : 999
  };
}).sort((x, y) => x.org_chart_tier - y.org_chart_tier);
const best = candidates.length ? candidates[0] : null;
return [{ json: { ...prev, best_contact: best } }];

// No org chart contact at all for this company (real, observed limit on
// very small companies) -- write everything Enrich Company + Corporate
// Hierarchy found, just with no contact fields. No credit spent on
// Enrich Contact since there's no personId to spend it on.
const ctx = $json;
const a = ctx.company || {};
const ws = $getWorkflowStaticData('global');
ws.rows = ws.rows || [];
ws.rows.push({
  place_cid: ctx.place_cid,
  enrich_status: ctx.match_status,
  address: a.street || null,
  city: a.city || null,
  state: a.state || null,
  phone: a.phone || null,
  hierarchy_type: ctx.hierarchy_type,
  parent_company: ctx.parent_company,
  contact_name: null,
  contact_title: null,
  contact_email: null,
  contact_phone: null,
  contact_linkedin: null,
  note: 'No org chart contact found for this company -- no Enrich Contact credit spent.'
});
return [{ json: ctx }];

// Real request shape confirmed live 2026-08-03: {data:{type:"ContactEnrich",
// attributes:{matchPersonInput:[{personId}], outputFields:[...]}}}.
// personId is an INTEGER.
const ctx = $json;
const outputFields = [
  'id', 'firstName', 'lastName', 'jobTitle', 'managementLevel',
  'email', 'phone', 'mobilePhone', 'externalUrls', 'contactAccuracyScore',
  'companyId', 'companyName'
];
return [{ json: {
  ...ctx,
  requestBody: { data: { type: 'ContactEnrich', attributes: { matchPersonInput: [{ personId: parseInt(ctx.best_contact.person_id, 10) }], outputFields } } }
} }];

// Merges everything (company + hierarchy + contact) into the final row and
// accumulates it. There is no dedicated LinkedIn field -- social URLs
// come back inside externalUrls as [{type, url}]; pull the first entry
// whose type mentions linkedin. contact_phone prefers phone, falls back
// to mobilePhone (both are real, separate fields ZoomInfo returns).
function parseResp(raw) {
  if (raw && typeof raw.data === 'string') {
    try { return JSON.parse(raw.data); } catch (e) { return raw; }
  }
  return raw;
}
const prev = $('Pick best org chart candidate').first().json;
const resp = parseResp($json || {});
const row = Array.isArray(resp.data) ? resp.data[0] : null;
const matchStatus = row && row.meta ? row.meta.matchStatus : (resp.errors ? 'ERROR' : 'NO_MATCH');
const c = row ? (row.attributes || {}) : {};
const a = prev.company || {};
const linkedin = Array.isArray(c.externalUrls) ? (c.externalUrls.find(u => String(u.type || '').toLowerCase().includes('linkedin')) || {}).url : null;
const ws = $getWorkflowStaticData('global');
ws.rows = ws.rows || [];
ws.rows.push({
  place_cid: prev.place_cid,
  enrich_status: prev.match_status,
  address: a.street || null,
  city: a.city || null,
  state: a.state || null,
  phone: a.phone || null,
  hierarchy_type: prev.hierarchy_type,
  parent_company: prev.parent_company,
  contact_name: [c.firstName, c.lastName].filter(Boolean).join(' ') || prev.best_contact.full_name || null,
  contact_title: c.jobTitle || prev.best_contact.title || null,
  contact_email: c.email || null,
  contact_phone: c.phone || c.mobilePhone || null,
  contact_linkedin: linkedin || null,
  note: matchStatus !== 'FULL_MATCH' ? `Enrich Contact match status was ${matchStatus} -- no contact credit charged.` : undefined
});
return [{ json: prev }];

// After the batch loop finishes, drain the accumulator into the final
// list. No dedupe needed here (input place_cids are already the caller's
// distinct selection), but the pull-and-clear pattern matches wf25/wf30
// for consistency.
const ws = $getWorkflowStaticData('global');
const rows = ws.rows || [];
ws.rows = [];
return [{ json: { rows } }];

// Build the workflow-20 bulk_update payload. Deliberately narrow field
// list -- only touches the fields this Enrich pass actually populated,
// never status/notes/attempts/archived/cold_draft/research fields on an
// existing doc (masked update, same safety rule as wf25/wf30). Rows with
// no enrichable data (NO_MATCH on Enrich Company) still get their
// last_seen_at bumped plus an enrich_status note, so the caller can see
// what happened without a separate error channel.
const rows = $json.rows || [];
const nowIso = new Date().toISOString();
const items = rows.map(r => {
  const fields = { last_seen_at: nowIso };
  if (r.enrich_status !== undefined) fields.enrich_status = r.enrich_status;
  if (r.address !== undefined && r.address !== null) fields.address = r.address;
  if (r.city !== undefined && r.city !== null) fields.city = r.city;
  if (r.state !== undefined && r.state !== null) fields.state = r.state;
  if (r.phone !== undefined && r.phone !== null) fields.phone = r.phone;
  if (r.hierarchy_type !== undefined) fields.hierarchy_type = r.hierarchy_type;
  if (r.parent_company !== undefined) fields.parent_company = r.parent_company;
  if (r.contact_name !== undefined) fields.contact_name = r.contact_name;
  if (r.contact_title !== undefined) fields.contact_title = r.contact_title;
  if (r.contact_email !== undefined) fields.contact_email = r.contact_email;
  if (r.contact_phone !== undefined) fields.contact_phone = r.contact_phone;
  if (r.contact_linkedin !== undefined) fields.contact_linkedin = r.contact_linkedin;
  return { id: r.place_cid, fields };
});
return [{ json: { enriched: items.length, rows, writerBody: { collection: 'site_outreach', action: 'bulk_update', items } } }];

const build = $('Build write payload').first().json;
const wrote = $json;
return [{ json: { ok: true, enriched: build.enriched, rows: build.rows, writerResponse: wrote } }];
